/**
 * Shared by the inline loader and its module-only fallback; no generated byte table is imported.
 *
 * The preference rule is src/ui/outfit.ts `loadRiderOutfit` (a valid `?outfit=` for this page, else the committed
 * `trials.riderOutfit`, else mustard; `street` / `race` alias their first design) and src/ui/best.ts `loadBikeChoice`
 * (`trials.bikeClass`, else rookie) — restated here in one storage read because the 8 KB inline cannot afford the
 * shared chain (ask 43 round 2: the outfit × class table alone is +200 B); `outfit.test.ts` holds the two equal.
 */
import type { RiderOutfit } from '../core/types';
import type { DeclaredBootTotals } from './asset-totals';

export function selectedBootTotals(totals: DeclaredBootTotals, search: string): { heroModels: number; bootArt: number } {
  const pick = (v: string | null): RiderOutfit | null => ({ street: 'street-mustard', race: 'race-bluewhite' } as Record<string, RiderOutfit>)[v as string] ?? (v && v in totals.heroModels ? v as RiderOutfit : null);
  let stored: string | null = null;
  let pro = false;
  try {
    stored = localStorage.getItem('trials.riderOutfit');
    pro = localStorage.getItem('trials.bikeClass') === 'pro';
  } catch {
    /* storage unavailable: the defaults */
  }
  return { heroModels: totals.heroModels[pick(new URLSearchParams(search).get('outfit')) ?? pick(stored) ?? 'street-mustard'][pro ? 1 : 0], bootArt: totals.bootArt };
}
